import { LitElement, html, css } from 'lit'

customElements.define('radio-group', class extends LitElement{

	static get properties(){return {
		key: {type: String, reflect: true},
		deselectable: {type: Boolean},
		multiple: {type: Boolean}
	}}

	static get styles(){return css`
		:host {
			display: inline-flex;
			flex-wrap: wrap;
			outline: none;
			border-radius: 4px;
			vertical-align: middle;
			box-sizing: border-box;
		}

		:host([hidden]) {
			display: none !important;
		}

		:host(:not([slot="control"])[focused]) {
			box-shadow: 0 0 0 2px var(--theme);
			transition: 200ms boxShadow;
		}

		:host([slot="control"]) {
			--radio-segment-min-width: 1em;
		}

		:host ::slotted(radio-btn){
			margin-right: 1em;
		}

		slot[name="before"]::slotted(*) {
			margin-bottom: .25em;
		}

		slot[name="after"]::slotted(*) {
			margin-top: .25em;
		}

		:host([segment]) main {
			align-self: flex-start;
			/* justify-self: flex-start; */
			background-color: var(--theme-bgd-accent, #ccc);
			--radio-segment-radius: 6px;
			border-radius: var(--radio-segment-radius);
			padding: var(--radio-segment-padding, .25rem);
			display: inline-flex;
			flex-grow: 1;
		}

		:host([segment][slot="control"]) {
			background-color: transparent !important;
		}

		:host([segment][pill]) {
			--radio-segment-radius: 1em;
		}

		:host([segment][stacked]) main {
			flex-direction: column;
			width: 100%;
			box-sizing: border-box;
		}

		:host([segment][disabled]) {
			color: var(--theme-text-accent, #888);
		}

		:host([segment]) ::slotted(radio-btn){
			flex-grow: 1;
			margin-right: 0;
			--radio-display: none;
			--radio-btn-label-padding: 0;
    		justify-content: center;
			border-radius: var(--radio-segment-radius);
			font-size: var(--radio-segment-font-size, 0.8em);
			padding: var(--radio-segment-btn-padding, var(--radio-segment-padding, .25em));
			min-width: var(--radio-segment-min-width, 5em);
			font-weight: bold;
		}

		:host([segment][slot="control"]) ::slotted(radio-btn){
			margin-bottom: calc(-1 * var(--padX) / 2);
    		/* margin-top: calc(-1 * var(--padX) / 4); */
		}

		:host([segment]) main {
			gap: 2px;
		}

		:host([segment][slot="control"]) main {
			padding: 0;
		}

		:host([segment][cols]) main {
			display: grid;
		}
		
		:host([segment][cols="2"]) main { grid-template-columns: repeat(2, 1fr); }
		:host([segment][cols="3"]) main { grid-template-columns: repeat(3, 1fr); }
		:host([segment][cols="4"]) main { grid-template-columns: repeat(4, 1fr); }
		:host([segment][cols="5"]) main { grid-template-columns: repeat(5, 1fr); }
		:host([segment][cols="6"]) main { grid-template-columns: repeat(6, 1fr); }

		:host([segment][stacked]) ::slotted(radio-btn){
			padding: calc(var(--radio-segment-btn-padding, var(--radio-segment-padding, .25em))*1.5);
			justify-content: left;
			line-height: 1.1em;
		}

		:host([segment]) ::slotted(radio-btn[active]) {
			background-color: var(--radio-segment-active-bgd, var(--theme-bgd, #fff));
			color: var(--radio-segment-active-color, inherit);
		}

		:host([segment="theme"]) ::slotted(radio-btn[active]) {
			background-color: var(--radio-segment-active-bgd, var(--theme, #2196F3));
			--theme-text: var(--radio-segment-active-color, var(--theme-bgd, #fff));
			color: var(--theme-text);
			--theme-text-rgb: var(--dark-text-rgb);
		}

		:host([segment="theme"][disabled]) ::slotted(radio-btn[active]) {
			background-color: color-mix(in srgb, var(--radio-segment-active-bgd, var(--theme, #2196F3)) 20%, transparent) !important;
		}

		:host([segment="inverse"]) ::slotted(radio-btn[active]) {
			background-color: var(--theme-inverse-bgd);
			--theme-text: var(--theme-inverse-text);
			color: var(--theme-text);
			--theme-text-rgb: var(--theme-inverse-text-rgb);
		}

		:host([segment]:not([disabled]):not([focused])) ::slotted(radio-btn:not([active]):hover) {
			background-color: var(--radio-segment-hover-bgd, var(--theme-bgd-accent2, #eee));
		}

		:host-context(b-animated-bgd):host([segment]) ::slotted(radio-btn) {
			z-index: 1;
			background: none;
			transition: color var(--animated-bgd-duration, 300ms);
			transition-timing-function: var(--animated-bgd-timing);
		}

		:host-context(b-animated-bgd):host([segment]) ::slotted(radio-btn[active]) {
			color: var(--animated-bgd-text-color, var(--theme-text));
		}
	`}

	render(){return html`
		<slot name="before"></slot>
		<main part="main">
			<slot></slot>
		</main>
		<slot name="after"></slot>
	`}
	
	constructor() {
		super()
		
		this.deselectable = false
		this.multiple = false
		
		this.addEventListener('change', this._onChange, true)
		
		this.addEventListener('keydown', e=>{
			if( ['ArrowLeft', 'ArrowUp'].includes(e.code) ){
				e.preventDefault()
				e.stopPropagation()
				this.nav(-1)
			}else if( ['ArrowRight', 'ArrowDown'].includes(e.code) ){
				e.preventDefault()
				e.stopPropagation()
				this.nav(1)
			}
		})

		/* add `focused` to support tabindex navigation */
		this.addEventListener('focus', e=>{
			this._setFocused = setTimeout(()=>{
				this.setAttribute('focused', '')
			},10)
		})
		
		this.addEventListener('blur', e=>{
			this.removeAttribute('focused')
		})

		// dont show "focused" when clicking inside, only when using keyboard
		this.addEventListener('mousedown', e=>{
			setTimeout(()=>{
				clearTimeout(this._setFocused)
				this.removeAttribute('focused')
			})
		})

		this.onChildrenChange = this.onChildrenChange.bind(this)
		const observer = new MutationObserver(this.onChildrenChange);
		observer.observe(this, {attributes: false, childList: true, subtree: false});
	}

	onChildrenChange(e){
		this.radios = Array.from(this.querySelectorAll('radio-btn'))
	}
	
	connectedCallback(){
		super.connectedCallback()

		if( !this.hasAttribute('tabindex') )
			this.setAttribute('tabindex', '0')

		this.radios = Array.from(this.querySelectorAll('radio-btn'))
		this.value = this.value
	}
	
	nav(dir=1){

		if( this.multiple ) return

		let i = this.radios.indexOf(this.active)
		
		if( i == undefined ) i = dir < 0 ? this.radios.length-1 : 0
		else i += dir
		
		if( i >= this.radios.length ) i = 0
		else if( i < 0 ) i = this.radios.length-1
		
		this.value = this.radios[i].value
		this._onChange({target:this.radios[i]})
	}
	
	_onChange(e){
		
		if( e.target == this ) return

		if( this.multiple )
			return this.value = this.active.map(el=>el.value)
		
		if( this.deselectable )
			this.value = e.target.active ? e.target.value : null
		else
			this.value = e.target.value
		
		this.setAttribute('value', this.value||'')
		e.stopPropagation&&e.stopPropagation()
		
		this._didChange()
	}

	_didChange(){
		var event = new CustomEvent('change', {
			bubbles: true,
			composed: true,
			detail: {
				value: this.value
			}
		});
		
		this.dispatchEvent(event)
	}
	
	get active(){
		if( this.multiple ) return this.radios?.filter(el=>el.active)
		return this.radios?.find(el=>el.active)
	}
	
	get value(){
		let radio = this.active

		if( this.multiple ) return radio.length ? radio.map(el=>el.value) : this.getAttribute('value')?.split(',').filter(Boolean)

		return radio ? radio.value : this.getAttribute('value')
	}
	
	set value(val){

		if( !this.multiple && Array.isArray(val) ){
			val = val[0]
		}

		(this.radios||[]).forEach(el=>{

			if( this.multiple )
				el.active = val.includes(el.value)
			else if( el.value == val || (!el.value && !val && el.value !== false && val !== false) )
				el.active=true
			else
				el.active=false
		})
		this.setAttribute('value', val||'')
	}
	
	get disabled(){ return this.hasAttribute('disabled') }
	set disabled(val=true){
		val ? this.setAttribute('disabled', '') : this.removeAttribute('disabled')
		this.radios.forEach(el=>el.disabled=val)
	}
	
})

export default customElements.get('radio-group')
