import { LitElement, html, css } from 'lit'
import './sort-btn'
import './sort-dir-btn'
import './filters-view'
import './layout-btn'
import './search'
import '../../../elements/toggle-btn'
import '../../../elements/toggle-view'
import GroupByPopover from '../group-by/popover'

customElements.define('b-list-toolbar', class extends LitElement{

    static get properties(){return {
        key: {type: String},
        count: {type: Number},
    }}
    
    static listeners = {
        coll: {'toggle-grouping': 'toggleGrouping'}
    }

    constructor(){
        super()
        this.count = 0
    }

    static get styles(){return css`
        :host {
            display: flex;
            align-items: center;
            min-width: 0;
            position: relative;
            background: linear-gradient(to bottom, transparent, var(--theme-bgd));
        }

        :host(.selection-bar-shown) > * {
            visibility: hidden;
        }

        [hidden] { display: none; }

        b-list-sort-btn {
            flex-shrink: 0;
            margin-left: auto;
        }

        b-btn {
            color: var(--toolbarTextColor);
        }

        .scroller {
            display: flex;
            overflow-y: auto;
            align-items: center;
            overflow: -moz-scrollbars-none;
            flex: 1;
        }

        .scroller > * {
            flex-shrink: 0;
        }

        .scroller::-webkit-scrollbar { width: 0 !important; height: 0 !important; }

        b-list-sort-btn,
        b-list-sort-btn + b-list-filters {
        }

        .after {
            margin-left: auto;
            display: flex;
            align-items: center;
        }

        .count {
            align-self: stretch;
            display: flex;
            align-items: center;
            margin: 0 .25em;
            /* border-right: 2px solid rgba(0, 0, 0, 0.1); */
            /* padding: 0 .75em 0 .25em; */
            
        }

        .controls {
            display: inline-grid;
        }

        .controls > b-icon {
            font-size: .8em;
            padding: .2em .35em;
            color: rgba(0, 0, 0, 0.4);
        }

        .controls > b-icon:hover {
            color: #333;
        }

        /* plain muted number (not a chip); shown after the view title instead when there is one */
        .count > span {
            display: flex;
            justify-content: center;
            align-items: center;
            padding: 0 .35em;
            flex-shrink: 0;
            order: var(--count-order, 2);
            font-size: .9em;
            font-weight: 500;
            font-variant-numeric: tabular-nums;
            color: var(--theme-text-accent);
        }

        /* (shown in a badge over the list instead) */
        .count {
            display: none !important;
        }

        [name="before"] { order: 1; }
        .count { order: 4; }
        .scroller { order: 3; }
        .after { order: 4; }

        .scroller[empty] {
            display: none;
        }

        .toggle-sidebar { order: 100; position: relative; }
        .toggle-sidebar b-label {
            position: absolute;
            top: 1px;
            right: 1px;
            pointer-events: none;
        }


        /* small: one line (filter chips are hidden; the filters sheet shows them) */
        @container (max-width: 599px) {

            slot {
                display: flex;
            }

            /* the toolbar scrolls if even the title, filters, and sort don't fit (ex: a long title) */
            :host {
                overflow-x: auto;
                scrollbar-width: none;
            }

            :host::-webkit-scrollbar { display: none; }

            /* filters and sort stay; the btns on the right give way first (and scroll) */
            .scroller {
                flex: 0 0 auto;
            }

            .after {
                flex-shrink: 1000;
                min-width: 2.75em; /* (at least one btn shows) */
                overflow-x: auto;
                scrollbar-width: none;
            }

            .after::-webkit-scrollbar { display: none; }

            .after > * {
                flex-shrink: 0;
            }

            b-list-sort-btn {
                border-left: none;
                margin-left: 0;
                padding-left: 0;
            }

        }

        /* (holds the groupings; they're chosen in the group by popover) */
        slot::slotted(b-list-group-by) {
            display: none;
        }
    `}

    // the groupings (b-list-group-by in the scroller slot)
    get groupByView(){
        let slot = this.shadowRoot?.querySelector('slot[name="scroller"]')
        return slot?.assignedElements({flatten: true}).find(el=>el.tagName == 'B-LIST-GROUP-BY')
            || this.coll?.groupByView
    }

    // (btn click or the G shortcut)
    toggleGrouping(e){
        let btn = this.shadowRoot.querySelector('.grouping')
        let view = this.groupByView
        if( !btn || btn.hidden || !view ) return
        GroupByPopover.open(view, btn)
    }

    // the count shows in a badge over the list (see ../index.js)
    updated(changed){
        super.updated?.(changed)
        let list = this.getRootNode()?.host
        if( changed.has('count') && list ) list.resultCount = this.count
    }

    get hasGrouping(){
        return this.coll?.applyGrouping || this.filters?.opts?.applyGrouping
    }

    // labels of the groupings that are on
    get groupedBy(){
        return (this.groupByView?.valuesList || []).filter(d=>d.on).map(d=>d.label)
    }

    render(){
        let groupedBy = this.groupedBy

        return html`
        <slot name="before"></slot>

        <div class="count"><span>${Number(this.count||0).toLocaleString()}</span></div>

        <div class="scroller" ?empty=${!this.sorts&&!this.filters.size}>
        <b-mouse-scroll-horz></b-mouse-scroll-horz>

            ${!this.filters||this.filters.opts.show===false?'':html`
                <b-list-filters .filters=${this.filters}></b-list-filters>
            `}

            <b-btn icon="group_by" class="grouping" lg clear pill
                tooltip=${groupedBy.length ? `Grouped by ${groupedBy.join(', ')} (G)` : 'Group by (G)'}
                @click=${this.toggleGrouping} ?hidden=${!this.hasGrouping}></b-btn>

            <slot name="scroller" @slotchange=${()=>this.requestUpdate()}></slot>

            ${!this.sorts?'':html`
                <b-list-sort-btn .sorts=${this.sorts}></b-list-sort-btn>
            `}

        </div>
        
        <div class="after">

            ${!this.filters||!this.filters.showSearch?'':html`
            <b-list-search-bar @keydown=${this.onKeyDown} 
                placeholder=${this.filters.searchOptions.placeholder}></b-list-search-bar>
            `}

            ${!this.layouts?'':html`
                <b-list-layout-btn .layouts=${this.layouts} pill text></b-list-layout-btn>
            `}

            <slot name="refresh-btn"></slot>

            <slot name="after"></slot>

            <slot></slot>
        </div>
    `
    }

    set term(term){
        let termInput = this.shadowRoot.querySelector('b-list-search-bar')

        if( termInput )
            termInput.value = term

        this._termChanged(term)
    }

    onKeyDown(e){
        let target = e.target
        let ts = this.filters.searchOptions.delay

        clearTimeout(this._keydownTimeout)
        this._keydownTimeout = setTimeout(_=>{
            this._termChanged(target.value)
        }, ts)
    }

    _termChanged(term){
        // same term or both falsy
        if( term == this.filters.term 
        || (!term && !this.filters.term) ) return

        this.filters.term = term

        this.dispatchEvent(new CustomEvent('filter-term-changed', {
            bubbles: true,
            composed: true,
            detail: {
                term: term
            }
        }))
    }

})

export default customElements.get('b-list-toolbar')