import {titleize} from '../../../util/string'
import Emitter from 'component-emitter'
import CollMap from '../../../util/collmap'
import SortsPopover from '../toolbar/sorts-popover'

export default class Sorts extends CollMap {

    get _storeKey(){ return 'b-list:'+this.key+':sort'}

    get value(){
        // first time getting value, get it from local storage
    	if( this.__value === undefined ){
			this.__value = this.key && JSON.parse(localStorage.getItem(this._storeKey)) || {}
        }

        return this.__value
    }

    set value(val){ this._setValue(val)}

    _setValue(val, {silent=false}={}){

        if( (!val || Object.keys(val).length == 0) && this.__defaultSort )
            val = this.__defaultSort

        let didChange = JSON.stringify(this.__value) != JSON.stringify(val)

        this.__value = val

        if( this.key ){
            if( val == null || val == undefined )
                localStorage.removeItem(this._storeKey)
            else
                localStorage.setItem(this._storeKey, JSON.stringify(val))
        }

        this.forEach(sort=>sort.selected=this.value[sort.key])

        if( !silent && didChange )
            this.emit('change', val)
    }

    get unset(){
        return Object.keys(this.value).length == 0 
    }

    use(sorts){

        if( sorts.db ){
            this.sortOnDB = true
            delete sorts.db
        }

        if( sorts.defaults ){
            let defaultVals = {}

            sorts.defaults.map(key=>{

                if( !sorts[key] ) return

                defaultVals[key] = {
                    desc: sorts[key].desc || false
                }
            })

            this.__defaultSort = defaultVals

            if( this.unset ){
                this.__value = defaultVals
                localStorage.setItem(this._storeKey, JSON.stringify(defaultVals))
            }

            delete sorts.defaults
        }

        if( sorts == this.__lastSorts )
            return

        this.__lastSorts = sorts
        
        this.clear()

        for( let key in sorts ){
            let sort = new Sort(key, sorts[key])
            sort.sorts = this
            sort.selected = this.value[key]
            this.set(key, sort)
        }

        let currentValue = this.value
        let didChangeCurrentValue = false

        // remove invalid sorts they may have been in local storage
        for( let key in currentValue ){
            if( !this.get(key) ){
                didChangeCurrentValue = true
                delete currentValue[key]
            }
        }

        if( didChangeCurrentValue ){
            // no more current value, default
            if( this.__defaultSort && Object.keys(currentValue).length == 0 ){
                currentValue = this.__defaultSort
            }

            this._setValue(currentValue, {silent: true})
        }        
    }

    map(fn){
        let resp = []
        this.forEach((v, key)=>resp.push(fn(v, key)))
        return resp
    }

	get label(){
        let active = this.active
        return active.length == 0 ? 'None' : active.map(sort=>sort.label).join(', ')
	}

	get active(){
        let active = []
        Object.keys(this.value).forEach(key=>{
            if( this.get(key) )
                active.push( this.get(key) )
        })
        return active
	}

    // presets, the active sorts (drag to reorder), and the rest (see ../toolbar/sorts-popover.js)
    showMenu(el){
        SortsPopover.open(this, el)
    }

	sort(data){
        // return
		let sorts = this.active
        let hasGrouping = this.list?.coll?.applyGrouping || this.list.filters?.opts?.applyGrouping

        // if collection is grouping, then let always include a "grouping" sort first
        if( hasGrouping ){

            // user defined, else create our own
            let groupingSort = this.get('grouping') || this._groupingSort
            
            if( !this.get('grouping') ){
                groupingSort = new Sort('grouping', {
                    desc: false,
                    sortBy(m){ return m.sortLabelPartial }
                })
                groupingSort.sorts = this
                this._groupingSort = groupingSort
            }
                
            // always sort by grouping first
            sorts.unshift(groupingSort)
        }

		return new Promise(resolve=>{
			
			if( sorts.length == 0 ) return resolve(data)

            data.sort(function (m1, m2) {

                for( let sort of sorts ){

                    let val = sort.sortCompare(m1, m2);

                    // the sort compare found different values
                    if( val !== false )
                        return val
                }

            });

			resolve(data)
		})	
	}

}


Emitter(Sorts.prototype)


class Sort {
    
    constructor(key, attrs){
        this.key = key

        if( typeof attrs == 'function' )
            attrs = {sortBy: attrs}

        this.attrs = attrs
    }

    get sortBy(){
        return this.attrs.sortBy || (m=>m.get?.(this.key) || m[this.key])
    }

    get label(){
        return this.attrs.label || titleize(this.key)
    }

    get description(){
        return this.attrs.description || null
    }

    get isDesc(){
        return this.selected ? this.selected.desc : (this.attrs.desc || false )
    }

    sortCompare(m1, m2){
        let v1 = this.sortBy(m1)
        let v2 = this.sortBy(m2)

        if( v1 > v2 ) return this.isDesc ? -1 : 1
        if( v1 < v2 ) return this.isDesc ? 1 : -1

        return false
    }

}
